const fs = require('node:fs')
const path = require('node:path')
const ts = require('typescript')
const vm = require('node:vm')
const root = path.resolve(__dirname, '../../..')
const source = fs.readFileSync(path.join(root, 'apps/mobile/src/components/completionGeometry.ts'), 'utf8')
const sheet = fs.readFileSync(path.join(root, 'apps/mobile/assets/completion-pixel/cat-stamp-pixel-v1.json'), 'utf8')
const code = source.replace(/^import sheet .*$/m, `const sheet = ${sheet}`)
fs.writeFileSync(path.join(root, 'docs/design-review/mobile-completion/completion-geometry.js'),
  '// Generated by apps/mobile/scripts/export-completion-preview.cjs from the mobile geometry.\n'
  + ts.transpileModule(code, { compilerOptions: { module: ts.ModuleKind.ES2022, target: ts.ScriptTarget.ES2022 } }).outputText)
const pawModule = fs.readFileSync(path.join(root, 'apps/mobile/assets/original-paw.ts'), 'utf8')
const paw = JSON.parse(pawModule.split('export const ORIGINAL_PAW_SVG = ')[1].trim())
fs.writeFileSync(path.join(root, 'docs/design-review/mobile-completion/original-paw.svg'), paw)
const mask = {}
vm.runInNewContext(ts.transpileModule(fs.readFileSync(path.join(root, 'apps/mobile/assets/completion-pixel/paw-mask.ts'), 'utf8'), {
  compilerOptions: { module: ts.ModuleKind.CommonJS }
}).outputText, { exports: mask })
const pixels = mask.PIXEL_PAW_ROWS.flatMap((row, y) => [...row].flatMap((pixel, x) =>
  pixel === '1' ? [`<rect x="${x}" y="${y}" width="1" height="1" fill="white"/>`] : [])).join('')
fs.writeFileSync(path.join(root, 'docs/design-review/mobile-completion/pixel-paw.svg'),
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" width="52" height="52" shape-rendering="crispEdges">${pixels}</svg>\n`)
